const fs = require('node:fs');
const path = require('node:path');
const root = path.join(__dirname, '..');
const source = fs.readFileSync(path.join(root, 'templates', 'valheim-install.py'), 'utf8').replace(/\r\n/g, '\n');
fs.writeFileSync(path.join(root, 'valheim-installer-source.js'),
  '// Generated by scripts/build-mod-installer.js; edit templates/valheim-install.py.\n' +
  `const VALHEIM_MOD_INSTALLER_SOURCE = ${JSON.stringify(source)};\n`);
